import json,html,pathlib
p=pathlib.Path(__file__).resolve().parent
scenes=[
('BẮT ĐẦU TỪ ĐÂU?','Lộ trình sự nghiệp kỹ sư AI',['Học gì?','Làm gì?','Chứng minh thế nào?'],['Một kỹ sư AI cần học gì để đi từ người mới đến chuyên gia?','Lộ trình bắt đầu từ nền tảng và phát triển qua từng dự án.','Mỗi bậc nghề nghiệp đòi hỏi năng lực và trách nhiệm khác nhau.']),
('01 / NỀN TẢNG','Xây móng trước khi xây AI',['Python + Git','Toán & xác suất','SQL + dữ liệu'],['Trước hết, học Python, Git và cách xử lý dữ liệu bằng SQL.','Song song là đại số tuyến tính, xác suất và thống kê.','Không cần biết hết mới bắt đầu, nhưng phải hiểu điều mình đang dùng.']),
('02 / HỌC MÁY','Đừng chỉ nhìn điểm số đẹp',['Dữ liệu → Mô hình','Huấn luyện ≠ kiểm thử','Đánh giá đúng bài toán'],['Tiếp theo, học cách chia dữ liệu, huấn luyện và đánh giá mô hình.','Một mô hình điểm cao vẫn có thể sai nếu dữ liệu bị rò rỉ.','Hãy làm bài toán nhỏ trước, hiểu vì sao nó đúng và khi nào nó sai.']),
('03 / DỰ ÁN ĐẦU TAY','Cho nhà tuyển dụng thấy sản phẩm',['Chatbot tiếng Việt','Đọc ảnh hóa đơn','Gợi ý sản phẩm'],['Dự án đầu tay có thể là chatbot, đọc hóa đơn hoặc gợi ý sản phẩm.','Đưa mã lên GitHub, viết hướng dẫn chạy và công bố cách đánh giá.','Một dự án hoàn chỉnh có giá trị hơn nhiều bản sao tutorial.']),
('04 / THỰC TẬP','Học cách làm việc trong một đội',['Đọc code của người khác','Nhận góp ý','Sửa lỗi & viết tài liệu'],['Khi đã có nền tảng và dự án, hãy tìm cơ hội thực tập.','Thực tập giúp rèn cách đọc code, nhận góp ý và phối hợp sửa lỗi.','Danh hiệu chưa quan trọng bằng việc mình tiến bộ qua từng nhiệm vụ.']),
('05 / FRESHER → JUNIOR','Tự làm được một phần việc',['Xử lý dữ liệu','Huấn luyện mô hình','Đưa lên API'],['Từ fresher lên junior, mục tiêu là tự hoàn thành một phần việc rõ ràng.','Không chỉ chạy trên máy cá nhân: hãy đưa mô hình thành một API.','Và biết kiểm tra đầu vào, ghi log, xử lý những lỗi thường gặp.']),
('06 / JUNIOR → MID-LEVEL','Chịu trách nhiệm từ đầu đến cuối',['Chất lượng','Độ trễ','Chi phí'],['Ở bậc mid-level, kỹ sư làm chủ vòng đời của một tính năng AI.','Chọn giải pháp, triển khai, theo dõi rồi cải thiện khi dữ liệu thay đổi.','Lúc này, chất lượng phải đi cùng tốc độ phản hồi và chi phí vận hành.']),
('07 / CHỌN HƯỚNG SÂU','Không cần giỏi tất cả cùng lúc',['Ngôn ngữ & GenAI','Thị giác máy tính','ML hệ thống / MLOps'],['Đến đây, hãy chọn một hướng để đào sâu theo sở thích và cơ hội.','Có thể là ngôn ngữ, thị giác máy tính, hoặc hệ thống và vận hành AI.','Dùng mô hình có sẵn vẫn cần đánh giá và thiết kế nghiêm túc.']),
('08 / MID-LEVEL → SENIOR','Từ làm được đến thiết kế đúng',['Kiến trúc hệ thống','Rủi ro & bảo mật','Hướng dẫn đồng đội'],['Senior không đơn giản là người đã làm đủ số năm.','Họ chọn kiến trúc phù hợp, dự báo rủi ro và hướng dẫn đồng đội.','Kỹ sư senior cần giải thích giá trị kinh doanh của giải pháp.']),
('09 / SAU SENIOR','Hai hướng đi, không chỉ một chiếc ghế',['Chuyên gia kỹ thuật','Lead / quản lý','Tác động lớn hơn'],['Sau senior, một kỹ sư AI có thể phát triển thành chuyên gia kỹ thuật.','Hoặc phát triển năng lực dẫn dắt đội ngũ và quản lý.','Không phải ai cũng cần làm sếp; điều quan trọng là phạm vi tác động.']),
('10 / KẾ HOẠCH HÀNH ĐỘNG','Bắt đầu bằng một vòng học nhỏ',['Học một kiến thức','Làm một tính năng','Đo → sửa → ghi lại'],['Nếu đang bắt đầu hôm nay, hãy chọn một bài toán nhỏ trong đời sống.','Mỗi vòng: học một kiến thức, làm một tính năng, đo kết quả rồi sửa.','Ghi lại tiến bộ bằng sản phẩm, thay vì chỉ đếm số chứng chỉ.']),
('ĐI ĐƯỜNG DÀI','Đừng chỉ nhìn đỉnh tháp',['Nền tảng vững','Sản phẩm thật','Học đều, đi bền'],['Các bậc nghề nghiệp là định hướng, không phải lịch thăng chức tự động.','Thu nhập còn tùy kỹ năng, công ty và thị trường ở từng thời điểm.','Bạn đang ở bậc nào, và sản phẩm tiếp theo của bạn sẽ là gì?'])]
D=12; total=len(scenes)*D
(p/'scenes.json').write_text(json.dumps(scenes,ensure_ascii=False,indent=2))
(p/'kich-ban.txt').write_text('\n\n'.join(f'{i+1}. {s[1]}\n'+ '\n'.join(s[3]) for i,s in enumerate(scenes)))
def human():
 return '''<svg class="person" viewBox="0 0 330 440"><g stroke="#302B32" stroke-width="7" stroke-linecap="round" stroke-linejoin="round"><path d="M126 343l-8 71m72-71 9 71" fill="none"/><path d="M118 412h-28m108 0h27"/><path d="M101 222L61 285m145-60 76-50"/><path d="M100 215q55-24 112 0l-5 134H104Z" fill="#ED9B45"/><path d="M125 267h58v49h-58Z" fill="#F4E9D5"/><ellipse cx="156" cy="143" rx="63" ry="71" fill="#F4D3B1"/><path d="M96 135l-5-45 26 8 12-28 25 17 27-28 10 39 26 1-4 39-24-27-20 14-22-22-19 26Z" fill="#302B32"/><path d="M131 144v11m48-11v11m-48 25q24 24 48-2" fill="none"/></g></svg>'''
def robot():
 return '''<svg class="robot" viewBox="0 0 230 220"><g stroke="#302B32" stroke-width="6" stroke-linejoin="round"><path d="M61 154v38m109-38v38M33 100H10m188 0h23"/><path d="M33 55l165 3-2 105-161-4Z" fill="#C87562"/><path d="M115 55V30"/><circle cx="115" cy="22" r="9" fill="#ED9B45"/><path d="M72 90v23m85-23v23m-65 19q24 24 46-2" fill="none"/></g></svg>'''
css='''@font-face{font-family:Paper;src:url(assets/body.ttf)}@font-face{font-family:Paper;src:url(assets/bold.ttf);font-weight:700}*{box-sizing:border-box}body{margin:0;width:1920px;height:1080px;overflow:hidden;color:#302B32;font-family:Paper;background:#F4E9D5}.clip{position:absolute;inset:0;width:100%;height:100%}.scene-content{width:100%;height:100%;padding:65px 100px 200px;display:flex;flex-direction:column;gap:20px}.eyebrow{font-size:28px;font-weight:700;letter-spacing:3px;color:#AE3047}.headline{font-size:68px;line-height:1.2;max-width:1640px;margin:0;font-weight:700}.stage{flex:1;min-height:0;display:flex;align-items:center;gap:40px}.person{width:330px;height:440px;flex-shrink:0;transform:rotate(-2deg)}.robot{width:230px;flex-shrink:0;align-self:flex-end}.notes{display:flex;flex:1;gap:30px;align-items:center}.note{border:5px solid #302B32;border-radius:7px 12px 8px 14px;box-shadow:8px 9px 0 #302B3220;min-height:230px;flex:1;padding:28px 22px;display:flex;flex-direction:column;gap:25px;justify-content:center;transform:rotate(-2deg)}.note:nth-child(2){transform:rotate(2deg)}.note strong{font-size:48px;color:#AE3047}.note span{font-size:33px;line-height:1.35;font-weight:700}.subtitle{position:absolute;left:0;bottom:57px;width:100%;padding:0 135px;text-align:center;font-size:36px;font-weight:700;line-height:1.45}.footer{position:absolute;left:100px;bottom:18px;font-size:28px}.counter{position:absolute;right:100px;bottom:18px;font-size:28px;font-weight:700}.floor{position:absolute;left:0;top:835px;width:100%;height:3px;background:#302B32}.progress{position:absolute;bottom:0;left:0;height:8px;width:1920px;background:#AE3047;transform-origin:left}.sun{position:absolute;right:100px;top:75px;width:170px;height:170px;background:#E5C56D;border-radius:50%;opacity:.4}'''
parts=[];an=[];srt=[]
for i,(ey,title,notes,subs) in enumerate(scenes):
 start=i*D; bg=['#F4E9D5','#DDE9DF','#EEE0DC','#DDD8E5'][i%4]
 cards=''.join(f'<div class="note" style="background:{["#F7E5AC","#D3E4D3","#EBCFD5"][j]}"><strong>{j+1:02}</strong><span>{n}</span></div>' for j,n in enumerate(notes))
 parts.append(f'<section id="s{i}" class="clip" data-start="{start}" data-duration="{D+.4 if i<11 else D}" data-track-index="{i}" style="background:{bg};z-index:{i}"><div class="sun" data-layout-ignore></div><div class="scene-content"><div class="eyebrow">{ey}</div><h1 class="headline">{title}</h1><div class="stage">{human()}<div class="notes">{cards}</div>{robot()}</div></div><div class="floor" data-layout-ignore></div></section>')
 an.append(f'tl.from("#s{i}",{{opacity:0,duration:.4,ease:"sine.inOut"}},{start});tl.from("#s{i} .eyebrow",{{opacity:0,x:-25,duration:.4,ease:"power2.out"}},{start+.15});tl.from("#s{i} .headline",{{opacity:0,y:28,duration:.6,ease:"power3.out"}},{start+.3});tl.from("#s{i} .person",{{opacity:0,x:-45,duration:.65,ease:"back.out(1.4)"}},{start+.45});tl.from("#s{i} .note",{{opacity:0,y:40,stagger:.25,duration:.65,ease:"back.out(1.2)"}},{start+.7});tl.from("#s{i} .robot",{{opacity:0,scale:.7,duration:.6,ease:"bounce.out"}},{start+1.2});tl.to("#s{i} .robot",{{y:-10,repeat:4,yoyo:true,duration:1,ease:"sine.inOut"}},{start+2});')
 for j,sub in enumerate(subs):
  t=start+j*4
  parts.append(f'<div id="c{i}-{j}" class="subtitle" data-start="{t}" data-duration="4" data-track-index="20" style="z-index:30">{sub}</div>')
  def stamp(t): return f'{t//3600:02}:{t//60%60:02}:{t%60:02},000'
  srt.append(f'{len(srt)+1}\n{stamp(t)} --> {stamp(t+4)}\n{sub}\n')
(p/'phu-de.srt').write_text('\n'.join(srt))
(p/'index.html').write_text(f'<!doctype html><html lang="vi"><head><meta charset="utf-8"><script src="assets/gsap.min.js"></script><style>{css}</style></head><body><main id="root" data-composition-id="main" data-start="0" data-duration="{total}" data-width="1920" data-height="1080">'+''.join(parts)+'<div class="progress" style="z-index:50"></div></main><script>window.__timelines=window.__timelines||{};const tl=gsap.timeline({paused:true});'+''.join(an)+f'tl.from(".progress",{{scaleX:0,duration:{total},ease:"none"}},0);window.__timelines.main=tl;</script></body></html>')
